using System.Collections.Concurrent;
using System.Text.Json;

namespace CombatSolver;

internal static class ChoiceIndexCostProbe
{
    private sealed class Counts
    {
        internal long Calls, Comparisons, Ticks;
    }
    private static readonly ConcurrentDictionary<(int Options,bool Routing),Counts> Results = new();
    static ChoiceIndexCostProbe()
    {
        AppDomain.CurrentDomain.ProcessExit += (_,_) =>
        {
            string output=Environment.GetEnvironmentVariable("CHOICE_INDEX_COST_OUTPUT")
                ?? throw new InvalidOperationException("Missing diagnostic output.");
            var rows=Results.OrderBy(x=>x.Key.Options).ThenBy(x=>x.Key.Routing).Select(x=>new {
                options=x.Key.Options,routing=x.Key.Routing,calls=Volatile.Read(ref x.Value.Calls),
                comparisons=Volatile.Read(ref x.Value.Comparisons),
                cumulativeMilliseconds=Volatile.Read(ref x.Value.Ticks)*1000d/System.Diagnostics.Stopwatch.Frequency }).ToArray();
            File.WriteAllText(output,JsonSerializer.Serialize(new {
                diagnosticOnly=true,algorithmUnchanged=true,timedScope="previous-equal-index loop; includes comparison-count instrumentation; parallel accumulated wall duration is not request time", rows
            },new JsonSerializerOptions{WriteIndented=true}));
        };
    }
    internal static void Record(int options,bool routing,long comparisons,long ticks)
    {
        Counts c=Results.GetOrAdd((options,routing),static _=>new());
        Interlocked.Increment(ref c.Calls);Interlocked.Add(ref c.Comparisons,comparisons);
        Interlocked.Add(ref c.Ticks,ticks);
    }
}
